INSERT INTO categories(name) SELECT 'Trà trái cây' WHERE NOT EXISTS (SELECT 1 FROM categories WHERE name='Trà trái cây');
INSERT INTO categories(name) SELECT 'Trà hoa' WHERE NOT EXISTS (SELECT 1 FROM categories WHERE name='Trà hoa');
INSERT INTO categories(name) SELECT 'Trà nguyên bản' WHERE NOT EXISTS (SELECT 1 FROM categories WHERE name='Trà nguyên bản');
INSERT INTO products(category_id,name,description,price,color,fruit,tag,type) SELECT c.id,'Trà đào cam sả','Đào ngọt dịu · Cam vàng · Sả thơm',45000,'#f8d6a0','🍑','BEST SELLER','peach' FROM categories c WHERE c.name='Trà trái cây' AND NOT EXISTS (SELECT 1 FROM products WHERE name='Trà đào cam sả');
